"""Generated bytes/arrays and metadata only; never invokes actual capture."""
from datetime import datetime, timezone
from io import BytesIO
import ast
from hashlib import sha256
import inspect
import json
from pathlib import Path
import unittest
import zipfile

import numpy as np

import cs_source_bridge as b

ROOT = Path(__file__).resolve().parent.parent
OLD = ROOT / 'traditional_D_full2022_20261015_v2/raw_source_bridge.py'


def generated_row(at, *, price='10', volume='5', quote='50'):
    # All fixture prices are invented. No saved source arrays are loaded.
    return [str(at // 1000), price, '11', '9', price, volume,
            str((at + b.MINUTE - 1000) // 1000), quote, '1', '0', '0', '0']


def fake_zip(rows, *, symbol='BTCUSDT', period='2022-01', member=None,
             header=False, extra=False, symlink=False):
    text = ('open_time,open,high,low,close,volume,close_time,quote_volume,trades,a,b,c\n'
            if header else '')
    text += '\n'.join(','.join(row) for row in rows) + '\n'
    stream = BytesIO()
    with zipfile.ZipFile(stream, 'w', zipfile.ZIP_DEFLATED) as archive:
        name = member or f'{symbol}-1m-{period}.csv'
        info = zipfile.ZipInfo(name)
        if symlink:
            info.create_system = 3
            info.external_attr = 0o120777 << 16
        archive.writestr(info, text)
        if extra:
            archive.writestr('unselected.csv', 'unselected')
    return stream.getvalue()


def fake_month(count=4):
    times = np.arange(b.START, b.START + count * b.MINUTE, b.MINUTE, dtype=np.int64)
    values = dict(times=times, available_us=times + b.MINUTE)
    for symbol in b.S:
        for key in ('open', 'close', 'quote_volume', 'mark'):
            values[symbol + '_' + key] = np.full(count, 7., dtype=np.float64)
    # Preserve an explicit non-default quiet-NaN payload as exact source bits.
    values['BTCUSDT_mark'][1] = np.array([0x7ff8000000000007], dtype=np.uint64).view(np.float64)[0]
    return values


def container(values):
    stream = BytesIO(); np.savez_compressed(stream, **values)
    return stream.getvalue()


class GeneratedParserTests(unittest.TestCase):
    def test_selected_parser_source_is_exact_old_bytes(self):
        old = OLD.read_text()
        selected = old[old.index('def parse_original_zip('):old.index('\n\ndef _pins')]
        self.assertEqual(inspect.getsource(b.parse_original_zip).rstrip(), selected.rstrip())
        provenance = json.loads((Path(b.__file__).parent / 'CS2022_SOURCE_BRIDGE_PROVENANCE.json').read_bytes())
        self.assertEqual(sha256(selected.encode()).hexdigest(), provenance['selected_function_source_SHA256'])
        self.assertEqual(sha256(ast.dump(ast.parse(selected), include_attributes=False).encode()).hexdigest(), provenance['selected_function_AST_SHA256'])

    def test_original_month_normalizer_AST_unchanged_except_witnesses(self):
        original = ast.parse(OLD.read_text())
        current = ast.parse(Path(b.__file__).read_text())
        def loop(tree, function):
            fn = next(n for n in tree.body if isinstance(n, ast.FunctionDef) and n.name == function)
            return next(n for n in fn.body if isinstance(n, ast.For) and isinstance(n.target, ast.Name) and n.target.id == 'month')
        old_loop = loop(original, 'capture_and_normalize')
        new_loop = loop(current, 'capture_2022')
        skip = {'old_name', 'bits', 'numeric_witnesses'}
        kept = []
        for node in new_loop.body:
            if isinstance(node, ast.Assign):
                names = {n.id for target in node.targets for n in ast.walk(target) if isinstance(n, ast.Name)}
                if names & skip:
                    continue
            if isinstance(node, ast.If) and 'EXACT_OLD_NATIVE_NORMALIZED_MONTH_BYTES_REQUIRED' in ast.unparse(node):
                continue
            if isinstance(node, ast.Expr) and 'numeric_witnesses.append' in ast.unparse(node):
                continue
            kept.append(node)
        new_loop.body = kept
        self.assertEqual(ast.dump(new_loop, include_attributes=False), ast.dump(old_loop, include_attributes=False))

    def test_generated_monthly_both_families_and_header(self):
        rows = [generated_row(b.START), generated_row(b.START + b.MINUTE)]
        for family in ('klines', 'markPriceKlines'):
            for header in (False, True):
                raw = fake_zip(rows, header=header)
                parsed, proof = b.parse_original_zip(raw, symbol='BTCUSDT', period='2022-01', family=family)
                self.assertEqual(parsed, {b.START: tuple(rows[0]), b.START + b.MINUTE: tuple(rows[1])})
                self.assertEqual(proof['observed_minutes'], 2)
                self.assertEqual(proof['header_present'], header)

    def test_generated_daily_and_identical_duplicate(self):
        at = b.START + 2 * 86400000000
        row = generated_row(at)
        parsed, _ = b.parse_original_zip(fake_zip([row, row], period='2022-01-03'),
            symbol='BTCUSDT', period='2022-01-03', family='klines')
        self.assertEqual(parsed, {at: tuple(row)})

    def test_conflicting_duplicate_denied(self):
        one = generated_row(b.START); two = generated_row(b.START, price='10.5')
        with self.assertRaisesRegex(ValueError, 'CONFLICTING_DUPLICATE'):
            b.parse_original_zip(fake_zip([one, two]), symbol='BTCUSDT', period='2022-01', family='klines')

    def test_malformed_source_values_and_clocks_denied(self):
        original = generated_row(b.START)
        mutations = ((1, 'nan'), (1, '0'), (2, '8'), (3, '12'),
                     (5, '-1'), (7, '-1'), (0, str(b.START // 1000 + 1)),
                     (6, str((b.START + b.MINUTE) // 1000)))
        for column, value in mutations:
            row = list(original); row[column] = value
            with self.subTest(column=column, value=value), self.assertRaises(ValueError):
                b.parse_original_zip(fake_zip([row]), symbol='BTCUSDT', period='2022-01', family='klines')
        with self.assertRaises(ValueError):
            b.parse_original_zip(fake_zip([original[:-1]]), symbol='BTCUSDT', period='2022-01', family='klines')
        with self.assertRaises(ValueError):
            b.parse_original_zip(fake_zip([generated_row(b.START - b.MINUTE)]), symbol='BTCUSDT', period='2022-01', family='klines')

    def test_member_namespace_and_unsupported_scope_denied(self):
        row = generated_row(b.START)
        for kwargs in ({'member': '../BTCUSDT-1m-2022-01.csv'}, {'extra': True}, {'symlink': True}):
            with self.subTest(kwargs=kwargs), self.assertRaises(ValueError):
                b.parse_original_zip(fake_zip([row], **kwargs), symbol='BTCUSDT', period='2022-01', family='klines')
        for kwargs in ({'symbol': 'UNADMITTED'}, {'family': 'indexPriceKlines'}, {'period': '2023-01'}):
            args = dict(symbol='BTCUSDT', period='2022-01', family='klines'); args.update(kwargs)
            with self.subTest(kwargs=kwargs), self.assertRaises(ValueError):
                b.parse_original_zip(fake_zip([row]), **args)


class GeneratedContainerTests(unittest.TestCase):
    def test_all22_generated_numeric_fields_and_nan_bits_round_trip(self):
        a = fake_month(); witness = b.verify_normalized_numeric_bits(container(a), a)
        self.assertEqual(len(witness), 22)
        self.assertEqual(witness['BTCUSDT_mark']['raw_SHA256'], sha256(a['BTCUSDT_mark'].tobytes()).hexdigest())

    def test_modified_numeric_bit_denied(self):
        a = fake_month(); changed = {key: value.copy() for key, value in a.items()}
        changed['ETHUSDT_close'].view(np.uint64)[0] ^= np.uint64(1)
        with self.assertRaisesRegex(ValueError, 'NUMERIC_BITS_CHANGED'):
            b.verify_normalized_numeric_bits(container(changed), a)

    def test_different_nan_payload_denied(self):
        a = fake_month(); changed = {key: value.copy() for key, value in a.items()}
        changed['BTCUSDT_mark'][1] = np.nan
        with self.assertRaisesRegex(ValueError, 'NUMERIC_BITS_CHANGED'):
            b.verify_normalized_numeric_bits(container(changed), a)

    def test_wrong_schema_dtype_or_member_denied(self):
        a = fake_month()
        wrong = dict(a); wrong['times'] = wrong['times'].astype(np.float64)
        with self.assertRaisesRegex(ValueError, 'SCHEMA_REQUIRED'):
            b.verify_normalized_numeric_bits(container(wrong), wrong)
        wrong = dict(a); wrong['extra'] = np.ones(4)
        with self.assertRaisesRegex(ValueError, 'MEMBER_NAMESPACE_REQUIRED'):
            b.verify_normalized_numeric_bits(container(wrong), a)
        with self.assertRaisesRegex(ValueError, 'ARRAYS_REQUIRED'):
            b.verify_normalized_numeric_bits(container(a), {'times': a['times']})

    def test_old12_pins_are_exact_saved_metadata_only(self):
        raw = (ROOT / 'traditional_D_full2022_20261015_v2_source_preparation_attempt001/PREPARATION.json').read_bytes()
        self.assertEqual(sha256(raw).hexdigest(), 'a4afcb2eb87d28936ba8d28e17dca52406fd63bbec2070c2036da1d5633fd9cf')
        p = json.loads(raw)
        months = next(iter(p['cells'].values()))['input_binding']['provider_month_identity']['months']
        self.assertEqual(tuple(tuple(row) for row in months), b.OLD_NORMALIZED_MONTH_PINS)
        self.assertEqual(len(months), 12)
        self.assertEqual(sum(row[2] for row in months), 525600)

    def test_missing_and_ducktyped_actual_scopes_rejected_before_reads(self):
        class DuckScope:
            def validate_current(self, **kwargs):
                self.fail('Duck validator must never be called')
            def read_source(self, *args, **kwargs):
                self.fail('No source read is permitted')
        for scope in (None, object(), DuckScope()):
            with self.subTest(kind=type(scope).__name__), self.assertRaisesRegex(ValueError, 'SEALED_SOURCE_SCOPE_REQUIRED'):
                b.capture_2022('/not/a/source/root', source_scope=scope)

    def test_actual_entry_has_no_caller_validator_or_generated_flag(self):
        self.assertEqual(str(inspect.signature(b.capture_2022)), '(root, *, source_scope)')
        source = inspect.getsource(b._require_source_scope)
        self.assertIn('type(source_scope) is not cs_entry.SourcePreparationScope', source)
        self.assertIn('source_scope.validate_current(year=2022)', source)
        capture = inspect.getsource(b.capture_2022)
        self.assertLess(capture.index('_require_source_scope'), capture.index('def read('))
        self.assertNotIn('full_source', capture)
        self.assertNotIn('historical', str(inspect.signature(b.capture_2022)))


if __name__ == '__main__':
    unittest.main(verbosity=2)
